package vn.techflow.manager.task;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:testdb") @AutoConfigureMockMvc class TaskControllerTest{@Autowired MockMvc mvc;
 @Test void create()throws Exception{mvc.perform(post("/api/tasks").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"Video Docker\",\"topic\":\"Docker là gì?\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("TODO"));}
 @Test void validate()throws Exception{mvc.perform(post("/api/tasks").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"\"}")).andExpect(status().isBadRequest());}}
